18	package org.apache.solr.servlet;
19	
20	import java.util.concurrent.Semaphore;
21	import java.util.concurrent.TimeUnit;
22	import net.jcip.annotations.ThreadSafe;
23	import org.apache.solr.core.RateLimiterConfig;
24	
25	/**
26	 * Handles rate limiting for a specific request type.
27	 *
28	 * <p>The control flow is as follows: Handle request -- Check if slot is available -- If available,
29	 * acquire slot and proceed -- else reject the same.
30	 */
31	@ThreadSafe
32	public class RequestRateLimiter {
33	  // Slots that are guaranteed for this request rate limiter.
34	  private final Semaphore guaranteedSlotsPool;
35	
36	  // Competitive slots pool that are available for this rate limiter as well as borrowing by other
37	  // request rate limiters. By competitive, the meaning is that there is no prioritization for the
38	  // acquisition of these slots -- First Come First Serve, irrespective of whether the request is of
39	  // this request rate limiter or other.
40	  private final Semaphore borrowableSlotsPool;
41	
42	  private final RateLimiterConfig rateLimiterConfig;
43	  private final SlotMetadata guaranteedSlotMetadata;
44	  private final SlotMetadata borrowedSlotMetadata;
45	  private static final SlotMetadata nullSlotMetadata = new SlotMetadata(null);
46	
47	  public RequestRateLimiter(RateLimiterConfig rateLimiterConfig) {
48	    this.rateLimiterConfig = rateLimiterConfig;
49	    this.guaranteedSlotsPool = new Semaphore(rateLimiterConfig.guaranteedSlotsThreshold);
50	    this.borrowableSlotsPool =
51	        new Semaphore(
52	            rateLimiterConfig.allowedRequests - rateLimiterConfig.guaranteedSlotsThreshold);
53	    this.guaranteedSlotMetadata = new SlotMetadata(guaranteedSlotsPool);
54	    this.borrowedSlotMetadata = new SlotMetadata(borrowableSlotsPool);
55	  }
56	
57	  /**
58	   * Handles an incoming request. returns a metadata object representing the metadata for the
59	   * acquired slot, if acquired. If a slot is not acquired, returns a null metadata object.
60	   */
61	  public SlotMetadata handleRequest() throws InterruptedException {
62	
63	    if (!rateLimiterConfig.isEnabled) {
64	      return nullSlotMetadata;
65	    }
66	
67	    if (guaranteedSlotsPool.tryAcquire(
68	        rateLimiterConfig.waitForSlotAcquisition, TimeUnit.MILLISECONDS)) {
69	      return guaranteedSlotMetadata;
70	    }
71	
72	    if (borrowableSlotsPool.tryAcquire(
73	        rateLimiterConfig.waitForSlotAcquisition, TimeUnit.MILLISECONDS)) {
74	      return borrowedSlotMetadata;
75	    }
76	
77	    return null;
78	  }
79	
80	  /**
81	   * Whether to allow another request type to borrow a slot from this request rate limiter.
82	   * Typically works fine if there is a relatively lesser load on this request rate limiter's type
83	   * compared to the others (think of skew).
84	   *
85	   * @return returns a metadata object for the acquired slot, if acquired. If the slot was not
86	   *     acquired, returns a metadata object with a null pool.
87	   * @lucene.experimental -- Can cause slots to be blocked if a request borrows a slot and is itself
88	   *     long lived.
89	   */
90	  public SlotMetadata allowSlotBorrowing() throws InterruptedException {
91	    if (borrowableSlotsPool.tryAcquire(
92	        rateLimiterConfig.waitForSlotAcquisition, TimeUnit.MILLISECONDS)) {
93	      return borrowedSlotMetadata;
94	    }
95	
96	    return nullSlotMetadata;
97	  }
98	
99	  public RateLimiterConfig getRateLimiterConfig() {
100	    return rateLimiterConfig;
101	  }
102	
103	  // Represents the metadata for a slot
104	  static class SlotMetadata {
105	    private final Semaphore usedPool;
106	
107	    public SlotMetadata(Semaphore usedPool) {
108	      this.usedPool = usedPool;
109	    }
110	
111	    public void decrementRequest() {
112	      if (usedPool != null) {
113	        usedPool.release();
114	      }
115	    }
116	
117	    public boolean isReleasable() {
118	      return usedPool != null;
119	    }
120	  }
121	}
