                QueryRateLimiter.processConfigChange(
                    SolrRequest.SolrRequestType.QUERY,
                    v == null ? null : v.getRateLimiterConfig(),
                    properties);
            if (newConfig == null) {
              return v;
            } else {
              return new QueryRateLimiter(newConfig);
            }
          } catch (IOException e) {
            throw new UncheckedIOException(e);
          }
        });

    return false;
